  static const String firebase_google_admob_google_google_policies_google_com_privacy_google_6dfa4 = "\u{644}\u{627} \u{646}\u{628}\u{64a}\u{639} \u{627}\u{644}\u{628}\u{64a}\u{627}\u{646}\u{627}\u{62a} \u{627}\u{644}\u{634}\u{62e}\u{635}\u{64a}\u{629}. \u{646}\u{634}\u{627}\u{631}\u{643} \u{627}\u{644}\u{62d}\u{62f} \u{627}\u{644}\u{623}\u{62f}\u{646}\u{649} \u{627}\u{644}\u{644}\u{627}\u{632}\u{645} \u{641}\u{642}\u{637} \u{645}\u{639} \u{645}\u{642}\u{62f}\u{645}\u{64a} \u{627}\u{644}\u{62e}\u{62f}\u{645}\u{627}\u{62a} \u{627}\u{644}\u{630}\u{64a}\u{646} \u{64a}\u{634}\u{63a}\u{644}\u{648}\u{646} \u{627}\u{644}\u{62a}\u{637}\u{628}\u{64a}\u{642} \u{2014} \u{627}\u{644}\u{627}\u{633}\u{62a}\u{636}\u{627}\u{641}\u{629}\u{60c} \u{648}\u{645}\u{632}\u{648}\u{62f}\u{648} \u{627}\u{644}\u{630}\u{643}\u{627}\u{621} \u{627}\u{644}\u{627}\u{635}\u{637}\u{646}\u{627}\u{639}\u{64a}\u{60c} \u{648}\u{62e}\u{62f}\u{645}\u{629} \u{627}\u{644}\u{625}\u{634}\u{639}\u{627}\u{631}\u{627}\u{62a} (Firebase)\u{60c} \u{648}\u{645}\u{632}\u{648}\u{62f}\u{648} \u{627}\u{644}\u{62f}\u{641}\u{639}\u{60c} \u{648}\u{62c}\u{648}\u{62c}\u{644} \u{639}\u{646}\u{62f} \u{627}\u{644}\u{62f}\u{62e}\u{648}\u{644} \u{628}\u{62d}\u{633}\u{627}\u{628}\u{647}\u{627} \u{2014} \u{648}\u{628}\u{627}\u{644}\u{642}\u{62f}\u{631} \u{627}\u{644}\u{644}\u{627}\u{632}\u{645} \u{644}\u{62a}\u{642}\u{62f}\u{64a}\u{645} \u{627}\u{644}\u{62e}\u{62f}\u{645}\u{629}. \u{648}\u{642}\u{62f} \u{646}\u{641}\u{635}\u{62d} \u{639}\u{646} \u{645}\u{639}\u{644}\u{648}\u{645}\u{627}\u{62a} \u{625}\u{630}\u{627} \u{637}\u{644}\u{628}\u{647}\u{627} \u{627}\u{644}\u{642}\u{627}\u{646}\u{648}\u{646} \u{623}\u{648} \u{62c}\u{647}\u{629} \u{645}\u{62e}\u{62a}\u{635}\u{629}. \u{627}\u{644}\u{625}\u{639}\u{644}\u{627}\u{646}\u{627}\u{62a}: \u{62a}\u{639}\u{631}\u{636} \u{627}\u{644}\u{646}\u{633}\u{62e}\u{629} \u{627}\u{644}\u{645}\u{62c}\u{627}\u{646}\u{64a}\u{629} \u{648}\u{627}\u{644}\u{62a}\u{62c}\u{631}\u{64a}\u{628}\u{64a}\u{629}